  function updateAssetFields() {const type=$('[name="type"]',$('#dialog'))?.value;$$('.asset-fixed').forEach(el=>el.hidden=type!=='fixed');$$('.asset-bundle').forEach(el=>el.hidden=type!=='bundle');const version=$('[name="version"]',$('#dialog'));if(version)version.readOnly=true;}
  function serializeEntity(form) {
    const {kind,record:old}=modalContext;const fd=new FormData(form);const value=name=>String(fd.get(name)||'');const number=name=>Number(value(name)||0);const yes=name=>fd.has(name);const record={id:old.id||uid(),space:state.space};if(fd.has('accountId'))record.accountId=value('accountId');else if(old.accountId)record.accountId=old.accountId;
    const plain=names=>names.forEach(name=>record[name]=value(name));const numbers=names=>names.forEach(name=>record[name]=number(name));const checks=names=>names.forEach(name=>record[name]=yes(name));
    if(kind==='accounts'){plain(['name','note']);checks(['paused']);if(state.space==='test')record.testOutcome=value('testOutcome');}
    if(kind==='products'){plain(['title','description','sku','category','status','materialRights']);numbers(['stock']);record.priceCents=cents(value('price'),'售价');if(old.sourceProductId)record.sourceProductId=old.sourceProductId;record.images=lines(value('images'));record.variants=$$('[data-variant-id]',form).map(row=>({id:row.dataset.variantId,name:$('[name="variantName"]',row).value,priceCents:cents($('[name="variantPrice"]',row).value,'规格售价'),assetId:$('[name="variantAsset"]',row).value,quantity:Number($('[name="variantQuantity"]',row).value)}));}
    if(kind==='assets'){plain(['name','type','category','link','code','instructions']);numbers(['threshold']);record.version=Number(old.version||1);record.images=lines(value('images'));record.items=$$('.bundle-row',form).map(row=>({assetId:$('[name="bundleAsset"]',row).value,quantity:Number($('[name="bundleQuantity"]',row).value)}));}
    if(kind==='orders'){plain(['externalId','buyerId','buyerName','productId','variantId','paymentStatus','tradeStatus','note']);record.amountCents=cents(value('amount'));record.refundCents=cents(value('refund'));record.costCents=cents(value('cost'));}
    if(kind==='rules'){plain(['name','productId','variantId','assetId','thankYou']);numbers(['quantity','priority','delaySeconds']);checks(['enabled']);record.afterReceipt=value('giftTiming')==='afterReceipt';record.gifts=$$('.gift-row',form).map(row=>({assetId:$('[name="giftAsset"]',row).value,quantity:Number($('[name="giftQuantity"]',row).value)}));}
    if(kind==='replyRules'){plain(['name','productId','text']);numbers(['priority','maxReplies']);checks(['enabled','fallback','exact']);record.keywords=lines(value('keywords'));record.excludeProductIds=lines(value('excludeProductIds'));}
    if(kind==='customers'){plain(['buyerId','name','assigneeId','note']);checks(['pinned','blocked']);record.tags=value('tags').split(/[,，]/).map(v=>v.trim()).filter(Boolean);}
    if(kind==='afterSales'){plain(['orderId','type','status','reason','note']);record.dueAt=value('dueAt')?new Date(value('dueAt')).toISOString():'';record.requestedCents=cents(value('requested'));}
    if(kind==='interactionProfiles'){plain(['name','productId']);checks(['enabled']);record.actions=Object.fromEntries(['thankYou','receiptReminder','reviewRequest'].map(type=>[type,{enabled:yes(type+'Enabled'),delaySeconds:number(type+'Delay'),...(type==='reviewRequest'?{}:{text:value(type+'Text')})}]));}
    if(kind==='plans'){plain(['name','action','scheduledAt']);numbers(['frequencyMinutes']);checks(['enabled','paused']);record.productIds=fd.getAll('productIds');}
    if(kind==='members'){plain(['name','role']);checks(['enabled']);record.accountIds=fd.getAll('accountIds');}
    if(kind==='snippets'){plain(['name','group','text']);record.images=lines(value('images'));}
    if(kind==='integrations'){plain(['name','type','endpoint','model','scope','costNotice']);checks(['enabled']);if(value('apiKey'))record.apiKey=value('apiKey');}
    return {kind,record};
  }
  async function showDeliveryPreview(id,trial=false) {
    const preview=await call('delivery.preview',{orderId:id});const order=get('orders',id);modalContext={kind:'delivery',preview,orderId:id};
    openDialog(trial?'交付规则试运行':'核对本次交付',`${notice(`工作区：<strong>${e(t(state.space))}</strong> · 账号：${e(accountName(order?.accountId))}<br>买家：<strong>${e(order?.buyerName||preview.buyerId)}</strong> · ${e(preview.buyerId||'接收方未确认')}`)}${preview.eligible?'':notice((preview.reasons||['当前条件不满足交付']).map(e).join('<br>'),'warn')}${preview.afterReceiptDeferred?notice('本次只交付主资料。赠品与致谢保存本次版本，等待可信收货后单独预览与发送。'):''}${preview.space==='live'&&preview.afterReceiptNotice?notice(e(preview.afterReceiptNotice),'warn'):''}<h3>拟交付的完整内容</h3><div class="content-preview">${e(preview.text||'尚未生成可交付内容。请检查规则、资料绑定与库存。')}</div><p class="help">此预览不发送消息、不消耗库存。资料发送、买家阅读和平台发货状态分别记录。</p><div class="form-end">${btn('关闭','close-dialog')}${preview.eligible&&!trial?btn(state.space==='test'?'执行隔离测试交付':'确认发送给此买家','delivery-execute',`data-id="${e(id)}"`,'primary'):''}</div>`);
  }
  function showInventoryImport(assetId) {modalContext={kind:'inventoryImport'};openDialog('补充唯一库存',`<form id="inventory-import-form"><div class="form-grid"><div class="full">${select('assetId','唯一内容资料',rows('assets').filter(a=>a.type==='unique'),assetId)}</div><div class="full">${field('content','逐条唯一内容','','textarea','每行一条完整内容。每条可包含文本或兑换码，不把链接与提取码分开计数。',true)}</div>${field('cost','每条成本（元）','0.00')}${field('expiresAt','有效期','','date')}</div><p class="help">需要保留条目内换行时，请通过 CSV 导入，使用带引号的内容字段。</p><div class="form-end">${btn('取消','close-dialog')}<button type="submit" class="primary">检查并预览入库</button></div></form>`);}
