    window.LianpuUX.saveView({scopeKey:scopeKey(),route:state.route},{search:state.search,filter:state.filter,tab:state.tab});
    accountUI.reset();sessionEpoch++;modalContext=null;state.messageDraft=null;$("#message-form")?.remove();state.route=route;state.checked.clear();
